package com.brightloop.subscription;
import com.brightloop.catalog.Customer;import com.brightloop.plan.*;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.time.LocalDate;import java.util.ArrayList;import java.util.List;
@Entity @Table(name="subscriptions") public class Subscription{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(name="subscription_number",nullable=false,unique=true,length=40) String subscriptionNumber;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="customer_id",nullable=false) Customer customer;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="plan_id",nullable=false) Plan plan;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="discount_id") com.brightloop.discount.Discount discount;@Column(name="start_date",nullable=false) LocalDate startDate;@Column(name="expiry_date") LocalDate expiryDate;@Enumerated(EnumType.STRING) @Column(name="billing_frequency",nullable=false,length=20) BillingFrequency billingFrequency;@Column(name="payment_terms") String paymentTerms;@Column(nullable=false,length=20) String status="DRAFT";@Column(nullable=false) int quantity=1;@Column(name="unit_price",nullable=false,precision=12,scale=2) BigDecimal unitPrice;@Column(nullable=false,precision=14,scale=2) BigDecimal subtotal;@Column(name="tax_amount",nullable=false,precision=14,scale=2) BigDecimal taxAmount;@Column(name="discount_amount",nullable=false,precision=14,scale=2) BigDecimal discountAmount;@Column(name="grand_total",nullable=false,precision=14,scale=2) BigDecimal grandTotal;@Column(name="next_billing_date") LocalDate nextBillingDate;@Column(name="paused_on") LocalDate pausedOn;@Column(name="auto_close_on_expiry",nullable=false) boolean autoCloseOnExpiry=true;@Column(name="created_at",nullable=false,updatable=false) Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false) Instant updatedAt=Instant.now();@OneToMany(mappedBy="subscription",cascade=CascadeType.ALL,orphanRemoval=true) List<SubscriptionLine> lines=new ArrayList<>();
 protected Subscription(){}public Subscription(String number,Customer customer,Plan plan,LocalDate start,LocalDate expiry,String terms,int qty,BigDecimal unit,BigDecimal subtotal,BigDecimal tax,BigDecimal discount,BigDecimal total){this.subscriptionNumber=number;this.customer=customer;this.plan=plan;this.startDate=start;this.expiryDate=expiry;this.billingFrequency=plan.getBillingFrequency();this.paymentTerms=terms;this.quantity=qty;this.unitPrice=unit;this.subtotal=subtotal;this.taxAmount=tax;this.discountAmount=discount;this.grandTotal=total;this.autoCloseOnExpiry=plan.isAutoCloseOnExpiry();this.nextBillingDate=start;}
 public void addLine(SubscriptionLine line){lines.add(line);}public List<SubscriptionLine> getLines(){return lines;}public void setDiscount(com.brightloop.discount.Discount d){discount=d;}public com.brightloop.discount.Discount getDiscount(){return discount;}@PreUpdate void touch(){updatedAt=Instant.now();}public Long getId(){return id;}public String getSubscriptionNumber(){return subscriptionNumber;}public Customer getCustomer(){return customer;}public Plan getPlan(){return plan;}public LocalDate getStartDate(){return startDate;}public LocalDate getExpiryDate(){return expiryDate;}public BillingFrequency getBillingFrequency(){return billingFrequency;}public String getPaymentTerms(){return paymentTerms;}public String getStatus(){return status;}public int getQuantity(){return quantity;}public BigDecimal getUnitPrice(){return unitPrice;}public BigDecimal getSubtotal(){return subtotal;}public BigDecimal getTaxAmount(){return taxAmount;}public BigDecimal getDiscountAmount(){return discountAmount;}public BigDecimal getGrandTotal(){return grandTotal;}public LocalDate getNextBillingDate(){return nextBillingDate;}public Instant getCreatedAt(){return createdAt;}public boolean isAutoCloseOnExpiry(){return autoCloseOnExpiry;}
 public void confirm(){if(!"DRAFT".equals(status)&&!"QUOTATION".equals(status))throw new IllegalStateException("Subscription cannot be confirmed from "+status);status="CONFIRMED";}
 public void activate(){if(!"CONFIRMED".equals(status))throw new IllegalStateException("Only confirmed subscriptions can be activated");status="ACTIVE";if(nextBillingDate==null)nextBillingDate=startDate;}
 public void pause(){if(!"ACTIVE".equals(status)||!plan.isAllowPause())throw new IllegalStateException("Plan does not permit pausing");status="PAUSED";pausedOn=LocalDate.now();}
 public void resume(){if(!"PAUSED".equals(status))throw new IllegalStateException("Only paused subscriptions can resume");if(pausedOn!=null&&nextBillingDate!=null){long days=java.time.temporal.ChronoUnit.DAYS.between(pausedOn,LocalDate.now());nextBillingDate=nextBillingDate.plusDays(Math.max(0,days));}status="ACTIVE";pausedOn=null;}
 public void close(boolean early){if(early&&!plan.isAllowEarlyClosure())throw new IllegalStateException("Plan does not permit early closure");if("CLOSED".equals(status))throw new IllegalStateException("Subscription is already closed");status="CLOSED";nextBillingDate=null;}
 public void billed(LocalDate next){nextBillingDate=next;}
 public void renew(){if(!plan.isAllowRenewal())throw new IllegalStateException("Plan does not permit renewal");if(!"CLOSED".equals(status)&&!"ACTIVE".equals(status))throw new IllegalStateException("Subscription cannot be renewed in its current state");if(expiryDate==null)throw new IllegalStateException("Subscription has no expiry date to renew");expiryDate=switch(billingFrequency){case DAILY->expiryDate.plusDays(1);case WEEKLY->expiryDate.plusWeeks(1);case MONTHLY->expiryDate.plusMonths(1);case YEARLY->expiryDate.plusYears(1);};nextBillingDate=LocalDate.now();status="ACTIVE";}
}
